{"success":true,"groups":[{"name":"scene_advanced","status":"activated","tools":[{"name":"scene_diff","description":"Compare a prior scene-tree snapshot against another snapshot (or current edited scene if 'after' omitted). Returns { changed, diff, added, removed }.","parameters":{"before":{"type":"string","required":true},"after":{"type":"string","required":false}},"annotations":{"readOnlyHint":true,"openWorldHint":false}},{"name":"scene_instantiate","description":"Instantiate PackedScene at scene_path under parent_path. Single mode: silent-return on name collision. Batch mode: pass instances array to spawn N copies with transforms.

Single: scene_path: "res://coin.tscn", parent_path: ".", as_name: "Coin"
Batch: scene_path: "res://coin.tscn", parent_path: ".", instances: [{name:"Coin1",position:{x:100,y:200},properties:{coin_value:5}}, ...]","parameters":{"parent_path":{"type":"string","required":true},"scene_path":{"type":"string","required":true},"as_name":{"type":"string","required":false,"description":"Single mode: instance name."},"transform":{"type":"string","required":false,"description":"Single mode: property overrides."},"instances":{"type":"array","required":false,"description":"Batch mode: array of {name?, position?, rotation?, scale?, properties?}. properties: arbitrary overrides applied after instantiation (e.g. {key_type: 'Gold'}). When present, spawns N instances as a batch. as_name and transform are ignored in batch mode."}},"annotations":{"readOnlyHint":false,"destructiveHint":false,"idempotentHint":false,"openWorldHint":false}}],"description":"Diff scenes and batch-instantiate nodes from packed scenes","match":"exact_name"},{"name":"scene_inheritance","status":"activated","tools":[{"name":"scene_create_inherited","description":"Create an inherited scene (.tscn) from a base scene — Godot's prefab variant pattern. Writes minimal TSCN text, works on all 4.2-4.7.","parameters":{"file_path":{"type":"string","required":true,"description":"Output .tscn path (e.g. 'res://scenes/slime_enemy.tscn')"},"base_scene":{"type":"string","required":true,"description":"Base scene path (e.g. 'res://scenes/enemy.tscn')"},"root_name":{"type":"string","required":false,"description":"Root node name override (default: base scene's root name)"}},"annotations":{"readOnlyHint":false,"openWorldHint":false,"destructiveHint":false}}],"description":"Create inherited scenes (variants) from base scenes","match":"exact_name"},{"name":"editor_advanced","status":"activated","tools":[{"name":"editor_screenshot","description":"Capture the editor viewport (NOT the running game — use runtime_screenshot for that). Pass node_path to focus one node. image_response_mode 'disk' saves the PNG and returns only its path.","parameters":{"save_path":{"type":"string","required":false,"description":"Destination .png used by image_response_mode disk/both (res:// or user://screenshots/); auto-named under user://screenshots/ when omitted."},"node_path":{"type":"string","required":false,"description":"Focus + capture a specific node instead of the full viewport"},"image_response_mode":{"type":"enum","required":false,"description":"How to return the capture: 'inline' (default) embeds the PNG; 'disk' persists it and returns only the path — use for very large captures or to conserve context tokens; 'both' does both. Files written to disk are always full resolution, regardless of image_detail."},"image_detail":{"type":"enum","required":false,"description":"Resolution of the returned inline image only. full = native; mid ≈ 1024 px long edge; low ≈ 512 px (gross layout/motion only — not for reading text). Does not affect files written to disk."},"force_foreground_editor":{"type":"boolean","required":false,"description":"If true, un-minimize + raise/focus the editor window before capturing (default false). Set it when driving from a terminal and editor_screenshot reports EDITOR_VIEWPORT_UNAVAILABLE; leave false in interactive use so your window isn't raised."}},"annotations":{"readOnlyHint":true,"openWorldHint":false}},{"name":"editor_refresh","description":"Refresh the editor's view of the filesystem — picks up new, changed, or deleted files (images, scenes, scripts, resources) and reloads open scripts. Call after creating files externally (e.g. Python, Bash) or after batch edits. With file_paths, targets specific files (O(1) per file). Without, does a full project rescan + reimport.","parameters":{"file_paths":{"type":"array","required":false,"description":"res:// paths to update; omit for full scan"}},"annotations":{"readOnlyHint":false,"openWorldHint":false,"destructiveHint":false}},{"name":"editor_wait_for_idle","description":"Poll EditorFileSystem.is_scanning() until idle or timeout_ms (default 10s, cap 30s). Use after asset.import, editor.refresh, or file mutations.","parameters":{"timeout_ms":{"type":"number","required":false}},"annotations":{"readOnlyHint":true,"openWorldHint":false}}],"description":"Capture editor screenshots, refresh the filesystem, and wait for idle","match":"exact_name"},{"name":"cleanup","status":"activated","tools":[{"name":"file_delete","description":"Delete any file under res:// and its .import companion. Auto-closes .tscn/.scn editor tabs on 4.5+ (tab_closed:true). Use for assets not covered by scene/script/resource.delete.","parameters":{"file_path":{"type":"string","required":true}},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},{"name":"scene_delete","description":"Delete .tscn at path and .uid companion. Auto-closes editor tab on 4.5+ (tab_closed:true). 4.2-4.4: blocks active scene (EDITED_SCENE); non-active tabs get phantom warnings. Refuses non-.tscn.","parameters":{"file_path":{"type":"string","required":true}},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},{"name":"script_delete","description":"Delete .gd/.cs/.gdshader/.gdshaderinc at file_path (and .uid companion). Refuses non-script paths (INVALID_PATH). No open-in-editor guard.","parameters":{"file_path":{"type":"string","required":true}},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},{"name":"resource_delete","description":"Delete the .tres/.res and its .uid companion at file_path. No active-use guard (Godot refs survive file deletion; detect orphans via editor_get_console).","parameters":{"file_path":{"type":"string","required":true}},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},{"name":"folder_delete","description":"Delete directory. recursive:false(default) requires empty. On 4.5+ closes one open scene tab; multiple in stale_tabs - use scene_close. Refuses project root, addons, open scripts (PATH_IN_USE).","parameters":{"path":{"type":"string","required":true},"recursive":{"type":"boolean","required":false}},"annotations":{"readOnlyHint":false,"destructiveHint":true,"openWorldHint":false}},{"name":"scene_close","description":"Close an open scene tab by file_path. Discards unsaved edits — save with editor_save_scene first. Auto-creates an empty scene when the last tab closes. NOT_FOUND if not open. Requires Godot 4.5+.","parameters":{"file_path":{"type":"string","required":true}},"annotations":{"readOnlyHint":false,"openWorldHint":false,"destructiveHint":true}}],"description":"Delete files, scripts, scenes, resources, and folders; close open scenes","match":"exact_name"}]}
